import type{PoolClient}from'pg';import{certifiedRows,insertFact}from'./facts.js';import{resolveLocation}from'./geography.js';
function readNum(v:any):number|null{if(v===null||v===undefined||v==='')return null;const n=Number(v);return Number.isFinite(n)?n:null}
function suppressed(flag:any,value:any):boolean{return value===null||value===undefined||value==='' ? String(flag??'').trim()!=='' : false}
export async function normalizeBusiness(c:PoolClient,run:string,naicsPolicy:any):Promise<number>{let n=0;const binds=(await c.query<any>(`SELECT * FROM zsl.zsl3_source_bindings WHERE build_run_id=$1 AND source_dataset IN('CBP','ZBP')`,[run])).rows;for(const b of binds){for(const raw of await certifiedRows(c,b)){const scope=b.source_dataset==='ZBP'?'POSTAL_CODE':b.source_geography;const loc=await resolveLocation(c,scope,raw.record);if(!loc)throw new Error(`ZSL3_BUSINESS_UNRESOLVED_GEOGRAPHY:${scope}:${raw.record_id}`);const sourceVocab=raw.record.NAICS2017!=null?'NAICS2017':raw.record.NAICS2022!=null?'NAICS2022':null;if(!sourceVocab)throw new Error('ZSL3_NAICS_VOCABULARY_UNKNOWN');const code=String(raw.record[sourceVocab]??'');const groups=naicsPolicy.featureGroups.filter((g:any)=>g.targetVocabulary===sourceVocab&&g.codes.includes(code));if(groups.length===0)continue;const eFlag=raw.record.ESTAB_F??null,empFlag=raw.record.EMP_F??null,payFlag=raw.record.PAYANN_F??null;const estabSupp=suppressed(eFlag,raw.record.ESTAB),empSupp=suppressed(empFlag,raw.record.EMP),paySupp=suppressed(payFlag,raw.record.PAYANN);const estab=estabSupp?null:readNum(raw.record.ESTAB),emp=empSupp?null:readNum(raw.record.EMP),pay=paySupp?null:readNum(raw.record.PAYANN);for(const g of groups){const feature=g.groupCode==='ELECTRONICS_RETAIL'?'electronics_establishments':g.groupCode==='WAREHOUSING_STORAGE'?'warehouse_establishments':g.groupCode==='GENERAL_MERCHANDISE'?'retail_establishments':null;if(!feature)continue;const miss=estabSupp?'SUPPRESSED':estab===null?'MISSING':'PRESENT';const fid=await insertFact(c,{run,locationId:loc,featureCode:feature,numericValue:estab,unit:'ESTABLISHMENT',sourceRole:b.source_dataset,binding:b,raw,sourceVariableCode:code,missingness:miss,suppressionFlag:eFlag});await c.query(`INSERT INTO zsl.zsl3_business_activity_facts(fact_id,source_naics_vocabulary,normalized_naics_vocabulary,naics_code,establishment_count,employment,annual_payroll,establishment_flag,employment_flag,payroll_flag) VALUES($1,$2,$2,$3,$4,$5,$6,$7,$8,$9)`,[fid,sourceVocab,code,estab,emp,pay,eFlag,empFlag,payFlag]);n++}}}return n}
